\label{lem:area}
For every spherical triangle,
\begin{equation}\label{eq:area}
\alpha+i\delta=4g\,e^{i\Omega/2}.
\end{equation}

\label{lem:construction}
\begin{enumerate}[label=\textup{(\roman*)}]
\item The circumcentre $X$ is
\begin{equation}\label{eq:X}
X=\frac{x(B+C)-\varepsilon\,B\times C}{\tan\beta\,(1+p)},
\end{equation}
and $\langle X,B\rangle=\langle X,C\rangle=x\cot\beta$.
\item The spherical triangle $XBC$ is isosceles with apex angle $2\beta$. Its base angle $\theta_a$ is acute and satisfies
\begin{equation}\label{eq:theta}
\cot\theta_a=x,\ \ \sin\theta_a=\frac{\cos\beta}{\cos(a/2)} .
\end{equation}
\item The $\beta$-point is $D=(1+\sec\beta)\,x\cot\beta\,X-\tfrac12\sec\beta\,(B+C)$, and it lies on the same side of $BC$ as $X$.
\end{enumerate}
The analogous statements hold for $Y,E$ and $Z,F$.

\label{rem:equivalent}
Lemma~\ref{lem:construction} provides an intrinsic description of the construction: on each side of $ABC$, erect the isosceles spherical triangle with apex angle $2\beta$ and acute base angles, the three apices being taken all outwards or all inwards. We stress that the condition on the base angles cannot be dropped: on each side of $BC$ there is also an isosceles triangle with the same apex angle and obtuse base angles, whose apex is $(-x(B+C)-\varepsilon B\times C)/(\tan\beta\,(1+p))$. In the plane the base angle equals $\pi/2-\beta$. On the sphere, \eqref{eq:theta} instead gives $\sin\theta_a>\cos\beta$, and therefore
\begin{equation}\label{eq:theta-bound}
\theta_a>\frac\pi2-\beta \text{ and } \Theta=\theta_a+\theta_b+\theta_c>\frac{3\pi}2-3\beta .
\end{equation}
For $\beta=\pi/3$ we have $\sec\beta=2$, and Lemma~\ref{lem:construction}(iii) gives $D+B+C=3x\cot\beta\,X$. Hence $X=(D+B+C)/|D+B+C|$ is the centroid of the equilateral spherical triangle $DBC$, which is the centre used in \cite{DNV24}.

\label{thm:angle}
Let $ABC$ be a non-equilateral spherical triangle satisfying \eqref{eq:domain}, let $X,Y,Z$ be obtained by the construction with sign $\varepsilon$, and put $\Phi=\Theta+\varepsilon\Omega/2$. Then $XYZ$ is equilateral if and only if $\cos\Phi=0$. In this case, let $\sigma=\sin\Phi\in\{1,-1\}$. If $\sigma=1$, then $\beta>\pi/3$. The triangle $XYZ$ is nondegenerate, and its side $\ell$ satisfies
\begin{equation}\label{eq:side}
\cos\ell=\frac{\sigma\cos\beta}{1-\sigma\cos\beta}.
\end{equation}

\label{rem:branches}
Since $0<\theta_a,\theta_b,\theta_c<\pi/2$ and $0<\Omega<2\pi$, the condition $\cos\Phi=0$ means that
\begin{equation}\label{eq:branches}
\Theta+\tfrac12\Omega\in\{\tfrac12\pi,\tfrac32\pi\} \text{ (outward)}, \ \ \Theta-\tfrac12\Omega\in\{-\tfrac12\pi,\tfrac12\pi\} \text{ (inward)}.
\end{equation}
The value $\pi/2$ corresponds to $\sigma=1$, and the other value in each case to $\sigma=-1$. Under this condition, one reads off from \eqref{eq:branches} that $\Theta>\pi/2$ if and only if $\varepsilon\sigma=-1$.

\label{prop:DEF}
Let $ABC$ be non-equilateral and satisfy \eqref{eq:domain}. Assume that the chosen construction gives an equilateral triangle $XYZ$ whose side $\ell$ is greater than $\pi/2$. Then $DEF$ is a nondegenerate equilateral triangle, whose side $m$ satisfies
\begin{equation}\label{eq:DEF}
\cos m=\frac{\cos\beta\,(1-\cos\beta+e_2\cos\beta)}{1-\cos\beta}
\end{equation}
and $0<m<\beta$.

\label{rem:DEF}
\begin{enumerate}[label=(\arabic*)]
\item The hypothesis that $ABC$ is not equilateral cannot be omitted. Take $\beta=\pi/3$ and $\cos a=\cos b=\cos c=-1/3$, so that $ABC$ is a face of a regular tetrahedron. Then $x=y=z=1/\sqrt3$ lies on $\mathcal{Q}_{1/2}$, and the outward construction gives $X=-A$, $Y=-B$, $Z=-C$. The triangle $XYZ$ is equilateral with side greater than $\pi/2$, but $D=E=F=-(A+B+C)$ and $m=0$.
\item The converse fails, even for a non-equilateral input. For $\beta=\pi/3$, take $\cos a=\cos b=-1/5$, $\cos c=7/10$, and construct outwards. This is a valid triangle with $(x,y,z)=\sqrt{3/5}\,(1,1,2)$. We find $\langle X,Y\rangle=-1/2$ and $\langle Y,Z\rangle=\langle Z,X\rangle=0$, so that the sides of $XYZ$ are $120^\circ,90^\circ,90^\circ$. Nevertheless, $DEF$ is equilateral, with $\langle D,E\rangle=\langle E,F\rangle=\langle F,D\rangle=-1/5$.
\item By Theorem~\ref{thm:angle}, the condition $\ell>\pi/2$ is equivalent to $\sigma=-1$, i.e.~the chosen construction selects $\kappa=\cos\beta$ in Theorem~\ref{thm:quadric}. We stress that mere membership in $\mathcal{Q}_{\cos\beta}$ would not suffice. In Example~\ref{ex:both} the parameter point lies on both quadrics, but the inward construction has $\ell<\pi/2$ and a non-equilateral $DEF$; Example~\ref{ex:second} gives another equilateral $XYZ$ with $\ell<\pi/2$ and non-equilateral $DEF$. Note also that, contrary to $\ell$, the side $m$ varies within each family covered by the proposition.
\end{enumerate}

\label{lem:inner}
Let $N_{xy}=\alpha xy-\varepsilon\delta(x+y)+pq-r$, and define $N_{yz}$, $N_{zx}$ cyclically; for instance $N_{zx}=\alpha zx-\varepsilon\delta(z+x)+rp-q$. Then
\begin{equation}\label{eq:XY}
\langle X,Y\rangle=\frac{N_{xy}}{\tan^2\beta\,(1+p)(1+q)}=\frac{N_{xy}}{4\sin^2\beta\cos^2\beta\,(1+x^2)(1+y^2)},
\end{equation}
and similarly for the other pairs.

\label{lem:identities}
For $\kappa\in\{\cos\beta,-\cos\beta\}$, let $Q_\kappa=\kappa^2(x^2+y^2+z^2)+2\kappa^3e_2-(1-\kappa)^2(1+2\kappa)$. Then
\begin{equation}\label{eq:alphaQ}
\alpha-4\kappa^3(1-e_2)=2Q_\kappa .
\end{equation}
If moreover $\varepsilon\delta=4\kappa^3(e_1-e_3)$, then
\begin{equation}\label{eq:NQ}
N_{xy}+4\kappa^3(1-\kappa)(1+x^2)(1+y^2)=2(xy-1)Q_\kappa .
\end{equation}

By \eqref{eq:theta-bound} we have $\Theta>\pi/2$, and $\Omega/2\in(0,\pi)$. For the outward construction we get $\Phi>\pi/2$, so that by \eqref{eq:branches} only $\Phi=3\pi/2$ is possible, with $\sigma=-1$, i.e.~$\kappa=\cos\beta$; this gives (ii). For the inward construction we get $\Phi>-\pi/2$, so that only $\Phi=\pi/2$ is possible, with $\sigma=1$, which is excluded by Theorem~\ref{thm:angle} since $\beta\le\pi/3$; this gives (i).

For (iii), let $\kappa=\cos\beta\in[1/2,1)$. Both eigenvalues and $K_\kappa$ are positive, so that $\mathcal{Q}_\kappa$ is an ellipsoid. A point of it in the open positive octant lies in the cube by \eqref{eq:K-bound}. As $\tan\beta\le\sqrt3$, each base angle exceeds $\pi/6$, so that $\Theta>\pi/2$ and $e_1>e_3$. If the point is not diagonal, Theorem~\ref{thm:quadric}(b) provides a triangle, and the construction is the outward one since $\kappa(e_1-e_3)>0$. Finally, near $(0,0,\sqrt{K_\kappa})$ the quadric $\mathcal{Q}_\kappa$ is the graph of
\begin{equation}\label{eq:zxy}
z(x,y)=-\kappa(x+y)+\sqrt{K_\kappa-x^2-y^2-2\kappa xy+\kappa^2(x+y)^2},
\end{equation}
and $z(x,y)>0$ for small $x,y\ge0$. Taking small $x,y>0$ with $x\ne y$ gives a two-parameter set of non-diagonal points of $\mathcal{Q}_\kappa$ in the open octant.
